'use client';
import { Fragment, useEffect, useRef, useState } from 'react';
import { cx } from '../lib/cx';
import { useControllable, useIsoLayoutEffect } from '../lib/hooks';
import { Icon } from '../lib/icons';
import { Fold, Spin, Swap, Tip } from '../lib/motion';
import '../designme.css';
import './web-search.css';

export interface WebPage {
  title: string;
  /** Like "stripe.com" */
  domain: string;
  /** Like "Oct 2026" */
  date?: string;
  /** reading while the agent opens it; the skipped ones say why */
  status: 'reading' | 'read' | 'skimmed' | 'paywall' | 'blocked' | 'timeout';
  /** The number the answer cites it by, as [1] */
  cite?: number;
}

export interface WebQuery {
  key: string;
  query: string;
  /** searching has the loader's highlight sweep; done shows the count and the time */
  status: 'searching' | 'done';
  /** How many results came back; 0 says No results */
  results?: number;
  /** Like "0.9s" */
  time?: string;
  /** This query asks the one before it again in other words */
  rewritten?: boolean;
  pages?: WebPage[];
}

export interface WebSearchProps {
  queries: WebQuery[];
  /** True once the searching and reading are over: the trail folds to its summary */
  done?: boolean;
  /** The answer, with sources cited as [1], [2]. Each number points at the page with that `cite` */
  answer?: string;
  /** Whether the trail is open. Left to the component, it folds once `done` turns true */
  open?: boolean;
  onOpenChange?: (open: boolean) => void;
  /** Without the panel, for a chat stream (true). Clean keeps its card either way */
  bare?: boolean;
  className?: string;
}

const STATUS: Record<WebPage['status'], [string, string]> = { reading: ['Reading', ''], read: ['Read', ''], skimmed: ['Skimmed', ''], paywall: ['Skipped: paywall', 'dm-warn'], blocked: ['Skipped: blocked', 'dm-warn'], timeout: ['Skipped: timeout', 'dm-warn'] };

/** The agent's web searches as a trail: each query and what came back, each page read, skimmed or skipped and why, a summary once done, and an answer whose citations light their pages. */
export function WebSearch({ queries, done = false, answer, open, onOpenChange, bare = true, className }: WebSearchProps) {
  const [inner, setInner] = useState(true);
  useEffect(() => { if (done && open === undefined) setInner(false); }, [done]); // eslint-disable-line react-hooks/exhaustive-deps
  const isOpen = open ?? inner;
  const setOpen = (o: boolean) => { if (open === undefined) setInner(o); onOpenChange?.(o); };
  // each query's pages are open while it is being read, and fold once it is done; a person can open any of them
  const [qOpen, setQOpen] = useControllable<Record<string, boolean>>(undefined, {});
  const [hot, setHot] = useState<number | null>(null);
  const pages = queries.flatMap(q => (q.pages || []).map(p => ({ ...p, q: q.key })));
  const sites = [...new Set(pages.map(p => p.domain))];
  const read = pages.filter(p => p.status === 'read' || p.status === 'skimmed').length;
  const current = queries.find(q => q.status === 'searching'), reading = pages.filter(p => p.status === 'reading').length;
  // the head says what is happening; the query and its pages are in the rows under it, so it repeats neither (owner, 18 Nov)
  const line = done ? `${queries.length} searches, ${read} pages read` : reading && !current ? 'Reading the pages' : 'Searching the web';
  const cited = (n: number) => pages.find(p => p.cite === n);
  // only changes of phase are announced
  const [said, setSaid] = useState('');
  const last = useRef('');
  useEffect(() => { const t = done ? `Done: ${line}` : current ? `Searching for ${current.query}` : ''; if (t && t !== last.current) { last.current = t; setSaid(t); } }, [done, current?.key]); // eslint-disable-line react-hooks/exhaustive-deps
  const hotPage = hot != null ? cited(hot) : undefined;
  // the trail grows and shrinks with what it holds, in every style (as grow() on designme.dev): its height follows its
  // content, eased, as searches arrive and as it folds
  const root = useRef<HTMLDivElement>(null), wrap = useRef<HTMLDivElement>(null);
  useIsoLayoutEffect(() => {
    const el = root.current, w = wrap.current;
    if (!el || !w || typeof ResizeObserver === 'undefined') return;
    let first = true;
    const fit = () => {
      const cs = getComputedStyle(el), h = Math.ceil(w.offsetHeight + parseFloat(cs.paddingTop) + parseFloat(cs.paddingBottom) + parseFloat(cs.borderTopWidth) + parseFloat(cs.borderBottomWidth));
      if (first) { el.style.transition = 'none'; el.style.height = h + 'px'; void el.offsetHeight; el.style.transition = ''; first = false; }
      else el.style.height = h + 'px';
    };
    const ro = new ResizeObserver(fit); ro.observe(w); fit();
    return () => { ro.disconnect(); el.style.height = ''; };
  }, []);
  return (
    <div data-dm="" ref={root} className={cx('dm-wsx', !bare && 'dm-panel', 'dm-growing', className)} style={bare ? { paddingInline: 0 } : undefined}>
      <div className="dm-grow" ref={wrap}>
      <button type="button" className="dm-wsx-h" aria-expanded={isOpen} onClick={() => setOpen(!isOpen)}>
        <span className="dm-wsx-ic">{done ? <Icon name="globe" size="xs" /> : <Spin />}</span>
        <Swap className={cx('dm-wsx-st', !done && 'dm-shim')}>{line}</Swap>
        <span className="dm-wsx-marks" aria-hidden="true">{sites.slice(0, 4).map(s => <span key={s} className={cx(hotPage?.domain === s && 'dm-hl')}>{s[0].toUpperCase()}</span>)}{sites.length > 4 && <span className="dm-n">+{sites.length - 4}</span>}</span>
        <Icon name="chev-d" size="xs" />
      </button>
      <Fold open={isOpen}>
        <div className="dm-wsx-list">
          {queries.map(q => {
            const has = !!q.pages?.length, auto = q.pages?.some(p => p.status === 'reading') ?? false, o = has && (qOpen[q.key] ?? auto);
            const lit = hotPage && hotPage.q === q.key;
            return (
              <div key={q.key} className={cx('dm-wsx-q', lit && !o && 'dm-hl', 'dm-enter')}>
                <button type="button" className={cx('dm-wsx-qh', !has && q.status === 'done' && 'dm-empty')} aria-expanded={o} onClick={() => has && setQOpen({ ...qOpen, [q.key]: !o })}
                  aria-label={q.status === 'done' ? `${q.query}: ${q.results ? q.results + ' results' : 'no results'}${q.time ? ', ' + q.time : ''}` : undefined}>
                  <Icon name="search" size="xs" /><span className={cx('dm-t', q.status === 'searching' && 'dm-shim')}>{q.query}</span>
                  <span className={cx('dm-n', q.status === 'searching' && 'dm-shim', q.status === 'done' && !q.results && 'dm-none')}>{q.status === 'searching' ? 'Searching' : q.results ? `${q.results} results` : 'No results'}</span>
                  <span className="dm-tm dm-num">{q.status === 'done' ? q.time : ''}</span><Icon name="chev-r" size="xs" />
                </button>
                {q.rewritten && <span className="dm-wsx-rw"><Icon name="refresh" size="xs" />Asked again in other words</span>}
                {has && <Fold open={o}><ul className="dm-wsx-rs">{q.pages!.map(p => (
                  <Tip key={p.title} label={`${p.title} · ${p.domain}`}>
                    <li tabIndex={0} className={cx('dm-wsx-r', 'dm-enter', p.status !== 'read' && p.status !== 'skimmed' && p.status !== 'reading' && 'dm-skip', lit && hotPage?.title === p.title && 'dm-hl')}
                      aria-label={`${p.title}, ${p.domain}${p.date ? ', ' + p.date : ''}: ${STATUS[p.status][0]}`}>
                      <span className="dm-wsx-fav" aria-hidden="true">{p.domain[0].toUpperCase()}</span>
                      <span className="dm-tx"><span className="dm-t">{p.title}</span><span className="dm-d">{p.domain}{p.date ? ' · ' + p.date : ''}</span></span>
                      <span className={cx('dm-tag', STATUS[p.status][1])}>{p.status === 'reading' ? <><Spin /><span className="dm-shim">Reading</span></> : STATUS[p.status][0]}</span>
                    </li>
                  </Tip>))}</ul></Fold>}
              </div>
            );
          })}
        </div>
      </Fold>
      {answer && <div className="dm-wsx-ans">{answer.split(/(\[\d+\])/).map((part, i) => { const m = part.match(/^\[(\d+)\]$/); if (!m) return <Fragment key={i}>{part}</Fragment>;
        const n = +m[1], p = cited(n);
        return <Tip key={i} label={p ? `${p.title} · ${p.domain}` : `Source ${n}`}><button type="button" className={cx('dm-wsx-cite', hot === n && 'dm-on')} aria-label={p ? `Source ${n}: ${p.title}, ${p.domain}` : `Source ${n}`}
          onPointerEnter={() => setHot(n)} onPointerLeave={() => setHot(null)} onFocus={() => setHot(n)} onBlur={() => setHot(null)}>{n}</button></Tip>; })}</div>}
      <p className="dm-wsx-sr" role="status">{said}</p>
      </div>
    </div>
  );
}

/* Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync. */
/* ---------- Web search ---------- */
/* the agent's searches as a trail: each query with what came back, each page with whether it was read, skimmed or skipped and
   why; once done it folds to one line, and the answer under it points back at its pages */
/* hover fills are a quiet 5%, so they show wherever the trail sits (on the stage, --dm-row is the stage's own colour) */
.dm-wsx{padding:6px;display:flex;flex-direction:column;font-size:13px;--dm-row:color-mix(in srgb,var(--dm-fg) 5%,transparent)}
/* the head's mark sits as far from the top as from the side: 16px in from the panel's edges (owner, 21 Nov: "more padding at
   the top of the card?") */
.dm-wsx-h{display:flex;align-items:center;gap:10px;width:100%;padding:10px;border-radius:var(--dm-r-in);text-align:left;font-size:13.5px;transition:background var(--dm-t-fast)}
@media (hover:hover) and (pointer:fine){.dm-wsx-h:hover{background:var(--dm-row)}}
/* every part on shared columns, in every style (owner, 18 Nov): the head's mark and every row's mark (the search glass, the
   asked-again arrow, a page's site initial) are centred in one 20px column, and every row's words start where the head's do */
.dm-wsx-ic{width:20px;height:20px;flex:none;display:grid;place-items:center;color:var(--dm-fg2)}
.dm-wsx-ic .dm-spin{width:11px;height:11px}
.dm-wsx-st{flex:1;min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.dm-wsx-h>.dm-i{color:var(--dm-muted);transition:transform .32s var(--dm-ease)}
.dm-wsx-h[aria-expanded="false"]>.dm-i{transform:rotate(-90deg)}
/* the sites it went to, as a small stack of initials, the rest counted */
/* side by side, never stacked over each other (owner, 18 Nov) */
.dm-wsx-marks{display:flex;align-items:center;gap:2px}
.dm-wsx-marks span{width:20px;height:20px;border-radius:50%;display:grid;place-items:center;background:var(--dm-chip);color:var(--dm-fg2);font-size:10.5px;font-weight:500;transition:background .2s,color .2s}
.dm-wsx-marks span.dm-n{background:var(--dm-surface);color:var(--dm-muted);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-line) 50%,transparent);font-size:10px}
.dm-wsx-marks span.dm-hl{background:var(--dm-fg2);color:var(--dm-surface)}
.dm-wsx-list{display:flex;flex-direction:column;gap:2px;padding:2px 0 var(--dm-s-1)}
.dm-wsx-q{display:flex;flex-direction:column}
.dm-wsx-qh{display:grid;grid-template-columns:20px minmax(0,1fr) auto auto 12px;align-items:center;column-gap:10px;width:100%;padding:6px 10px;border-radius:calc(10px * var(--dm-rk-m,var(--dm-rk)));text-align:left;transition:background var(--dm-t-fast)}
.dm-wsx-q.dm-hl>.dm-wsx-qh{background:var(--dm-row)}
@media (hover:hover) and (pointer:fine){.dm-wsx-qh:hover{background:var(--dm-row)}}
.dm-wsx-qh>.dm-i:first-child{justify-self:center;color:var(--dm-muted)}
.dm-wsx-qh .dm-t{min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.dm-wsx-qh .dm-n,.dm-wsx-qh .dm-tm{font-size:12px;color:var(--dm-muted);white-space:nowrap}
/* a query and its Searching have the loader's sweep (.shim) while it runs: their own colours step aside for it */
.dm-wsx-qh .dm-t:not(.dm-shim){color:var(--dm-fg)}
.dm-wsx-qh .dm-n.dm-shim{color:transparent}
@media (prefers-reduced-motion:reduce){.dm-wsx-qh .dm-n.dm-shim{color:var(--dm-fg)}}
.dm-wsx-qh .dm-n{margin-right:-2px}
.dm-wsx-qh .dm-n.dm-none{color:var(--dm-warn)}
.dm-wsx-qh>.dm-i:last-child{color:var(--dm-muted);transition:transform .32s var(--dm-ease)}
.dm-wsx-qh[aria-expanded="true"]>.dm-i:last-child{transform:rotate(90deg)}
/* a search that found nothing has no chevron and keeps no room for one: its count and time end where the chevrons and the
   pages' tags end (owner, 21 Nov) */
.dm-wsx-qh.dm-empty{grid-template-columns:20px minmax(0,1fr) auto auto}
.dm-wsx-qh.dm-empty>.dm-i:last-child{display:none}
.dm-wsx-rw{display:flex;align-items:center;gap:10px;padding:0 10px 2px;font-size:12px;color:var(--dm-muted)}
.dm-wsx-rw .dm-i{margin-inline:4px}
.dm-wsx-rs{list-style:none;margin:0;padding:2px 0 var(--dm-s-1);display:flex;flex-direction:column;gap:2px}
.dm-wsx-r{display:grid;grid-template-columns:20px minmax(0,1fr) auto;column-gap:10px;align-items:center;padding:5px 10px;border-radius:calc(9px * var(--dm-rk-m,var(--dm-rk)));transition:background var(--dm-t-fast);cursor:default}
.dm-wsx-r.dm-hl{background:var(--dm-row)}
@media (hover:hover) and (pointer:fine){.dm-wsx-r:hover{background:var(--dm-row)}}
.dm-wsx-r:focus-visible{outline-offset:-2px}
.dm-wsx-fav{width:20px;height:20px;border-radius:calc(6px * var(--dm-rk-s,var(--dm-rk)));display:grid;place-items:center;background:var(--dm-chip);color:var(--dm-fg2);font-size:10.5px;font-weight:500}
.dm-wsx-r .dm-tx{display:flex;flex-direction:column;min-width:0;line-height:1.35}
.dm-wsx-r .dm-t{white-space:nowrap;overflow:hidden;text-overflow:ellipsis;font-size:12.5px;color:var(--dm-fg)}
.dm-wsx-r .dm-d{font-size:11.5px;color:var(--dm-muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.dm-wsx-r.dm-skip .dm-t{color:var(--dm-muted)}
.dm-wsx-r .dm-tag .dm-spin{width:9px;height:9px}
/* on a hovered or lit row the grey Read and Skimmed chips lift to white (one step lighter in dark mode), so they stand out
   against the row's hover fill rather than melting into it (owner, 22 Nov), in every style */
.dm-wsx{--dm-wsx-lift:var(--dm-surface)}
:root[data-theme="dark"] .dm-wsx{--dm-wsx-lift:var(--dm-hover)}
@media (prefers-color-scheme:dark){:root:not([data-theme="light"]) .dm-wsx{--dm-wsx-lift:var(--dm-hover)}}
.dm-wsx-r .dm-tag{transition:background-color var(--dm-t-fast)}
@media (hover:hover) and (pointer:fine){.dm-wsx-r:is(:hover,.dm-hl) .dm-tag:not(.dm-warn){background:var(--dm-wsx-lift)}}
.dm-wsx-ans{padding:var(--dm-s-2) 10px 6px;font-size:13.5px;line-height:1.6;color:var(--dm-fg)}
.dm-wsx-ans:empty{display:none}
/* the number sits in the middle of its circle: its line is as tall as its figures, so a taller line round it (Clean's 22px
   answer lines set it 2.5px low) never moves it (owner, 21 Nov: "padding is off in this number") */
.dm-wsx-cite{display:inline-grid;place-items:center;min-width:18px;height:17px;padding:0 4px;margin:0 1px;border-radius:calc(5px * var(--dm-rk-s,var(--dm-rk)));background:var(--dm-chip);color:var(--dm-fg2);font-size:11px;line-height:1;font-weight:500;vertical-align:1px;transition:background var(--dm-t-fast),color var(--dm-t-fast)}
.dm-wsx-cite.dm-on{background:var(--dm-fg2);color:var(--dm-surface)}
@media (hover:hover) and (pointer:fine){.dm-wsx-cite:hover{background:var(--dm-fg2);color:var(--dm-surface)}}
.dm-wsx-sr{position:absolute;width:1px;height:1px;margin:-1px;padding:0;overflow:hidden;clip-path:inset(50%);white-space:nowrap}
/* Clean (lead and owner, 18 Nov): a card of its own, bare or not, as Reasoning trail is: a hairline-outlined round card
   with the search head on top and a hairline under it, everything on shared columns. Content sits 16px in from the card's
   edges. The head's spinner (a globe once done) sits in a 28px neutral tile, and every row's leading mark (a query's search
   glass, the asked-again arrow, a page's site initial) is centred in that same 28px column, so every row's words start where
   the head's do. A row's hover fill spans the content, from the tile's left edge to the content's right edge, never wider;
   the chevrons are centred in a 28px column at the end, the one the head's chevron circle (its quiet hover) fills. A row
   with no chevron (a page, a search that found nothing) keeps no room for one: its tag or time ends on the content's right
   edge (owner, 22 Nov). The answer is the card's own paragraph under a hairline. The card grows and
   shrinks with what it holds (grow()), so as the trail folds once the searching is done it eases down to the head and the
   answer, staying centred. Colour only for meaning: "No results" and a skipped page in the warning colour; sites, counts
   and pages read are grey */
:root[data-style="clean"] .dm-wsx.dm-wsx.dm-wsx,:root [data-style="clean"] .dm-wsx.dm-wsx.dm-wsx,:root [data-style="clean"].dm-wsx.dm-wsx.dm-wsx{padding:0;background:var(--dm-surface);box-shadow:var(--dm-shadow);border-radius:var(--dm-r-card);overflow:clip;container-type:inline-size}
/* on a phone the head drops its stack of site initials, so its words fit: "3 searches, 6 pages read" whole */
@container (max-width:400px){:root[data-style="clean"] .dm-wsx-marks,:root [data-style="clean"] .dm-wsx-marks,:root [data-style="clean"].dm-wsx-marks{display:none}}
:root[data-style="clean"] .dm-wsx.dm-growing,:root [data-style="clean"] .dm-wsx.dm-growing,:root [data-style="clean"].dm-wsx.dm-growing{overflow-clip-margin:0px}
/* the head's tile sits 16px from the top as from the side, and its chevron's circle 16px from the top and the right */
:root[data-style="clean"] .dm-wsx-h,:root [data-style="clean"] .dm-wsx-h,:root [data-style="clean"].dm-wsx-h{min-height:calc(28px + 2 * var(--dm-strip-y));padding:0 23px 0 16px;gap:12px;border-radius:0;font-size:13.5px}
@media (hover:hover) and (pointer:fine){:root[data-style="clean"] .dm-wsx-h:hover,:root [data-style="clean"] .dm-wsx-h:hover,:root [data-style="clean"].dm-wsx-h:hover{background:none}}
:root[data-style="clean"] .dm-wsx-h:focus-visible,:root [data-style="clean"] .dm-wsx-h:focus-visible,:root [data-style="clean"].dm-wsx-h:focus-visible{outline-offset:-2px;border-radius:var(--dm-r-card)}
:root[data-style="clean"] .dm-wsx-ic,:root [data-style="clean"] .dm-wsx-ic,:root [data-style="clean"].dm-wsx-ic{width:28px;height:28px;border-radius:calc(7px * var(--dm-rk-m,var(--dm-rk)));background:var(--dm-chip);box-shadow:inset 0 0 0 1px var(--dm-hair)}
:root[data-style="clean"] .dm-wsx-st,:root [data-style="clean"] .dm-wsx-st,:root [data-style="clean"].dm-wsx-st{font-weight:500}
:root[data-style="clean"] .dm-wsx-st:not(.dm-shim),:root [data-style="clean"] .dm-wsx-st:not(.dm-shim),:root [data-style="clean"].dm-wsx-st:not(.dm-shim){color:var(--dm-fg)}
:root[data-style="clean"] .dm-wsx-marks,:root [data-style="clean"] .dm-wsx-marks,:root [data-style="clean"].dm-wsx-marks{margin-right:2px}
:root[data-style="clean"] .dm-wsx-h>.dm-i,:root [data-style="clean"] .dm-wsx-h>.dm-i,:root [data-style="clean"].dm-wsx-h>.dm-i{width:14px;height:14px;border-radius:50%;box-shadow:0 0 0 7px transparent;transition:transform var(--dm-t) var(--dm-ease),background-color var(--dm-t-fast) var(--dm-ease),box-shadow var(--dm-t-fast) var(--dm-ease),color var(--dm-t-fast) var(--dm-ease)}
@media (hover:hover) and (pointer:fine){:root[data-style="clean"] .dm-wsx-h:hover>.dm-i,:root [data-style="clean"] .dm-wsx-h:hover>.dm-i,:root [data-style="clean"].dm-wsx-h:hover>.dm-i{background:var(--dm-row);box-shadow:0 0 0 7px var(--dm-row);color:var(--dm-fg)}}
/* the first row's words sit 16px under the divider, its hover box reaching out 6px round them (owner, 19 Nov: a body's
   first row sits 16px under a divider, no more), and the list ends as far under its last row */
:root[data-style="clean"] .dm-wsx-list,:root [data-style="clean"] .dm-wsx-list,:root [data-style="clean"].dm-wsx-list{gap:0;padding:10px 16px;border-top:1px solid var(--dm-line)}
:root[data-style="clean"] .dm-wsx-qh,:root [data-style="clean"] .dm-wsx-qh,:root [data-style="clean"].dm-wsx-qh{grid-template-columns:28px minmax(0,1fr) auto auto 28px;column-gap:12px;padding:6px 0;border-radius:calc(7px * var(--dm-rk-m,var(--dm-rk)));transition:background-color var(--dm-t-fast) var(--dm-ease)}
:root[data-style="clean"] .dm-wsx-qh>.dm-i,:root [data-style="clean"] .dm-wsx-qh>.dm-i,:root [data-style="clean"].dm-wsx-qh>.dm-i{justify-self:center}
:root[data-style="clean"] .dm-wsx-qh .dm-n,:root [data-style="clean"] .dm-wsx-qh .dm-n,:root [data-style="clean"].dm-wsx-qh .dm-n{margin-right:-4px}
:root[data-style="clean"] .dm-wsx-qh.dm-empty,:root [data-style="clean"] .dm-wsx-qh.dm-empty,:root [data-style="clean"].dm-wsx-qh.dm-empty{grid-template-columns:28px minmax(0,1fr) auto auto}
:root[data-style="clean"] .dm-wsx-qh .dm-n,:root [data-style="clean"] .dm-wsx-qh .dm-n,:root [data-style="clean"].dm-wsx-qh .dm-n,:root[data-style="clean"] .dm-wsx-qh .dm-tm,:root [data-style="clean"] .dm-wsx-qh .dm-tm,:root [data-style="clean"].dm-wsx-qh .dm-tm{font-variant-numeric:tabular-nums}
:root[data-style="clean"] .dm-wsx-rw,:root [data-style="clean"] .dm-wsx-rw,:root [data-style="clean"].dm-wsx-rw{padding:0 0 6px;gap:12px}
